const axios = require('axios');

async function getVideoInfo(url) {
  try {
    const response = await axios.post('https://api.viesnap.com/info', {
      url: url
    }, {
      headers: {
        'Content-Type': 'application/json'
      }
    });
    return response.data;
  } catch (error) {
    console.error('Error fetching video info:', error);
    throw error;
  }
}

// Contoh penggunaan:
const videoUrl = "https://vt.tiktok.com/ZS4cWtHop/";

getVideoInfo(videoUrl)
  .then(data => {
    m.reply(JSON.stringify(data, null, 2));
  })
  .catch(err => {
    m.reply('Terjadi kesalahan saat mengambil informasi video.');
  });
